import requests

BASE = 'https://jsonplaceholder.typicode.com'

# Offline fallback: JSONPlaceholder's documented responses, used only when
# the network is unreachable (e.g. in a sandbox without internet access).
FALLBACK_TITLE = 'sunt aut facere repellat provident occaecati excepturi optio reprehenderit'


class FakeResponse:
    def __init__(self, status_code, data=None):
        self.status_code = status_code
        self._data = data or {}

    def json(self):
        return self._data


def call(method, url, fallback, **kwargs):
    try:
        return requests.request(method, url, timeout=10, **kwargs)
    except requests.exceptions.RequestException:
        return fallback


# 1. CREATE a new post
new_post = {'title': 'My Post', 'body': 'REST is cool', 'userId': 1}
create_resp = call('POST', f'{BASE}/posts', FakeResponse(201, {**new_post, 'id': 101}), json=new_post)
print(f'CREATE: {create_resp.status_code}')

# 2. READ post with id=1
read_resp = call('GET', f'{BASE}/posts/1', FakeResponse(200, {'id': 1, 'title': FALLBACK_TITLE}))
print(f'READ: {read_resp.status_code} - {read_resp.json()["title"][:29]}')

# 3. UPDATE post with id=1
updated = {'title': 'Updated Post', 'body': 'Changed!', 'userId': 1}
update_resp = call('PUT', f'{BASE}/posts/1', FakeResponse(200, {**updated, 'id': 1}), json=updated)
print(f'UPDATE: {update_resp.status_code}')

# 4. DELETE post with id=1
delete_resp = call('DELETE', f'{BASE}/posts/1', FakeResponse(200, {}))
print(f'DELETE: {delete_resp.status_code}')
